import {createFacility} from './scene.js';
import {createEquipment} from './equipment.js';

export function renderPremiumHome({main,content,products,services,button,productCard}){
  const paused=matchMedia('(prefers-reduced-motion: reduce)').matches;
  main.innerHTML=`
  <section class="cinema-hero" aria-label="AEMS engineering solutions">
    <img class="cinema-image" src="assets/premium/cleanroom-hero.png" alt="Architectural visualisation of a modern pharmaceutical clean room" fetchpriority="high">
    <div class="cinema-shade"></div>
    <div class="wrap cinema-content"><div class="eyebrow">AEMS INFRA / CONCEPT TO COMMISSIONING</div><h1>Clean rooms. HVAC.<br>One engineering<br><em>partner.</em></h1><p>Purpose-built environments for pharmaceutical, healthcare, biotechnology and food processing. Every system connected. Every detail considered.</p><div class="actions">${button('contact.html','Discuss your project')}<a class="cinema-secondary" href="service.html">Explore our solutions <span>↗</span></a></div><div class="cinema-assurance"><span>◇</span> Design. Supply. Installation. Validation.</div></div>
    <div class="hero-caption"><span>01 — ENGINEERING THE ENVIRONMENT</span><small>Architectural concept visualisation</small></div>
    <a class="hero-scroll" href="#solutions" aria-label="Explore AEMS solutions"><span>SCROLL TO EXPLORE</span>↓</a>
  </section>
  <section class="capability-strip"><div class="wrap"><div><strong>One point of responsibility.</strong><span>Complete engineering, from the first idea to a working facility.</span></div><a href="cleanroomequipment.html">Clean rooms <span>↗</span></a><a href="hvacservices.html">HVAC systems <span>↗</span></a><a href="mepcontractors.html">MEP solutions <span>↗</span></a></div></section>
  <section class="section premium-intro"><div class="wrap"><div class="intro-grid"><div><div class="eyebrow">WELCOME TO AEMS</div><h2>Critical environments.<br><span>Extraordinary care.</span></h2></div><div><p>Aditya Electro Mechanical Solutions is a technology-based, knowledge-driven enterprise providing turnkey MEP and clean room solutions. We integrate your facility from concept to commissioning, with process efficiency at the heart of every decision.</p><a class="text-link" href="about.html">Get to know your engineering partner <span>↗</span></a></div></div><div class="intro-proof"><div><span>01</span><h3>Built around your process</h3><p>Customised environments, engineered for your requirements.</p></div><div><span>02</span><h3>Every discipline connected</h3><p>Mechanical, electrical and utility systems working as one.</p></div><div><span>03</span><h3>Support beyond handover</h3><p>Validation, maintenance and energy-efficient retrofits.</p></div></div></div></section>
  <section class="section immersive-solutions" id="solutions"><div class="wrap"><div class="section-head"><div><div class="eyebrow">OUR EXPERTISE</div><h2>Whatever your challenge.<br><span class="muted-title">We see the whole picture.</span></h2></div><p>Explore our capabilities. Find the right engineering support for your facility.</p></div><div class="solution-tabs" role="tablist" aria-label="Engineering solutions">${services.slice(0,5).map((s,i)=>`<button role="tab" id="solution-tab-${i}" data-solution="${i}" aria-controls="solution-panel" aria-selected="${i===0}" tabindex="${i===0?'0':'-1'}">${s[1]}</button>`).join('')}</div><div class="solution-feature" id="solution-panel" role="tabpanel" aria-labelledby="solution-tab-0"></div></div></section>
  <section class="section equipment-discovery" id="equipment-experience"><div class="wrap"><div class="section-head"><div><div class="eyebrow">INTERACTIVE EQUIPMENT STUDIO</div><h2>A closer look.<br><span class="muted-title">A clearer understanding.</span></h2></div><p>Rotate, zoom and explore. Get to know the engineering before you start a conversation.</p></div><div class="discovery-layout"><div class="discovery-copy"><span class="studio-label">3D EQUIPMENT EXPLORER</span><h3 id="discovery-title">Air handling unit</h3><p id="discovery-description">Air filtration and conditioning, brought together in a modular system.</p><div class="discovery-selector" role="group" aria-label="Choose equipment to explore">${[[11,'Air handling unit'],[8,'Air shower'],[6,'Pass box'],[0,'Clean room panels']].map(([index,label],i)=>`<button data-discovery="${index}" aria-pressed="${i===0}"><span>0${i+1}</span>${label}<b>↗</b></button>`).join('')}</div><a class="button" id="discovery-link" href="airhandlingunit.html">View full product <span>↗</span></a><small>Illustrative 3D models. Original specifications and product photographs are available on each product page.</small></div><div class="discovery-viewport" id="discovery-stage"></div></div></div></section>
  <section class="section premium-products"><div class="wrap"><div class="section-head"><div><div class="eyebrow">PURPOSE-BUILT EQUIPMENT</div><h2>Designed to perform.<br><span class="muted-title">Built to belong.</span></h2></div>${button('products.html','Explore all 14 products','light')}</div><div class="product-grid featured-products">${[products[11],products[8],products[6],products[0]].map(productCard).join('')}</div></div></section>
  <section class="industry-banner"><img src="assets/premium/cleanroom-hero.png" alt="Illustrative clean room environment" loading="lazy"><div class="industry-banner-shade"></div><div class="wrap"><div class="eyebrow">ENGINEERING WITH PURPOSE</div><h2>The environments<br>behind better outcomes.</h2><p>Dedicated solutions for the sectors where controlled conditions and reliable systems matter most.</p><div class="industry-pills"><a href="cleanroomequipment.html">Pharmaceutical <span>↗</span></a><a href="hvacservices.html">Healthcare <span>↗</span></a><a href="cleanroomequipment.html">Biotechnology <span>↗</span></a><a href="service.html">Food processing <span>↗</span></a></div></div></section>
  <section class="section facility-studio"><div class="wrap"><div class="facility-studio-heading"><div><div class="eyebrow">SEE HOW IT ALL CONNECTS</div><h2>Every system.<br><span class="muted-title">One complete environment.</span></h2></div><p>Explore the layers of a clean room: the space, the air, and the services that bring it to life.</p></div><div class="facility-studio-world"><div class="scene-shell"><div class="scene-canvas" role="img" tabindex="0"></div><div class="scene-toolbar" role="group" aria-label="Explore the 3D facility"><button data-scene="all" aria-pressed="true">◇ Facility</button><button data-scene="air" aria-pressed="false">≋ Airflow</button><button data-scene="exploded" aria-pressed="false">▱ Exploded</button></div><div class="scene-status"><button data-scene="motion" class="motion-button" aria-pressed="${paused}">${paused?'Play motion':'Pause motion'}</button><button data-scene="reset" class="motion-button">Reset view ↺</button></div></div><div class="studio-legend"><span><i></i>Clean room envelope</span><span><i></i>Air treatment & distribution</span><span><i></i>Integrated utilities</span><small>Concept model · Drag or use arrow keys to rotate</small></div></div></div></section>
  <section class="section premium-process"><div class="wrap"><div class="section-head"><div><div class="eyebrow">FROM IDEA TO OPERATION</div><h2>A clear process.<br><span class="muted-title">A confident next step.</span></h2></div><a class="text-link" href="contact.html">Start your project <span>↗</span></a></div><div class="premium-process-grid">${[['Listen & understand','We start with your process, your facility and your priorities.'],['Design & engineer','We coordinate the disciplines into one complete engineering solution.'],['Build & integrate','Equipment supply, installation and system integration, managed together.'],['Test & hand over','Validation, documentation and support to prepare your facility for operation.']].map(([h,p],i)=>`<div class="process-step"><span class="process-number">0${i+1}</span><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div></section>
  <section class="section premium-clients"><div class="wrap"><div class="section-head"><div><div class="eyebrow">RELATIONSHIPS THAT MATTER</div><h2>Our clients.<br><span class="muted-title">Our commitment.</span></h2></div><a class="text-link" href="clients.html">Explore our client portfolio <span>↗</span></a></div><div class="premium-logo-wall">${(content['clients.html']?.images||[]).slice(0,12).map((src,i)=>`<a href="clients.html"><img src="${src}" alt="AEMS client portfolio logo ${i+1}" loading="lazy"></a>`).join('')}</div></div></section>
  <section class="section customer-questions"><div class="wrap faq-layout"><div><div class="eyebrow">HELPING YOU GET STARTED</div><h2>A few good<br><span class="muted-title">questions.</span></h2><p>Have a project in mind? Our engineering team can help you work through the details.</p><a class="text-link" href="contact.html">Ask us a question <span>↗</span></a></div><div class="faq-list">${[
    ['Can AEMS deliver a complete turnkey project?','Yes. AEMS integrates clean room and MEP solutions from concept through design, supply, installation, testing and commissioning.'],
    ['Which industries do you work with?','AEMS serves pharmaceutical, healthcare, biotechnology and food processing environments, with customised environmental control and building services.'],
    ['Can you improve an existing HVAC system?','AEMS provides retrofit solutions for existing HVAC systems and air handling units. The engineering team can review your current system and discuss suitable improvements.'],
    ['What should I share for a project enquiry?','Tell us about your industry, process, facility location and the equipment or services you need. Include any available drawings or technical requirements in your email to our team.']
  ].map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div></div></section>
  <section class="customer-cta"><div class="wrap"><div><div class="eyebrow">LET’S BUILD THE RIGHT SOLUTION</div><h2>Your next project<br>starts with a conversation.</h2><p>Speak with our team about your clean room, HVAC, MEP or equipment requirements.</p></div><div class="customer-cta-actions">${button('contact.html','Discuss your project')}<a href="tel:+919000230419">Call +91 90002 30419 <span>↗</span></a><a href="mailto:info@aemsinfra.com">info@aemsinfra.com <span>↗</span></a></div></div></section>`;
  const solutionMedia=['assets/premium/cleanroom-hero.png','assets/premium/ahu-studio.png','assets/img/mep-home.png','assets/img/validations.png','assets/img/facility.png'];
  const solutionText=[
    'Modular clean rooms designed around your process. Panels, doors, equipment and environmental control, coordinated from concept to commissioning.',
    'Environmental control that works for your facility. Design, supply, installation and commissioning of HVAC systems, with retrofit and maintenance support.',
    'Mechanical, electrical and plumbing engineering under one roof. Connected building services with one coordinated approach to project delivery.',
    'Know how your environment performs. Clean room testing, filter integrity checks, environmental measurements and clear technical documentation.',
    'Keep critical utilities and process equipment working with dedicated engineering support, planned maintenance and equipment qualification.'
  ];
  function showSolution(index){const s=services[index];document.querySelector('#solution-panel').setAttribute('aria-labelledby',`solution-tab-${index}`);document.querySelector('#solution-panel').innerHTML=`<div class="solution-feature-image"><img src="${solutionMedia[index]}" alt="${s[1]} ${index<2?'concept visualisation':'from the AEMS service portfolio'}" loading="lazy"><span>${index<2?'ENGINEERING VISUALISATION':'AEMS SERVICE PORTFOLIO'}</span></div><div class="solution-feature-copy"><span class="feature-number">0${index+1} / OUR CAPABILITIES</span><h3>${s[1]}</h3><p>${solutionText[index]}</p>${button(s[0],'Explore this solution')}<a href="contact.html?product=${encodeURIComponent(s[1])}">Discuss your requirements ↗</a></div>`;document.querySelectorAll('[data-solution]').forEach((b,i)=>{b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1;});}
  document.querySelectorAll('[data-solution]').forEach((b,i)=>{b.addEventListener('click',()=>showSolution(i));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?4:(i+(e.key==='ArrowRight'?1:4))%5;showSolution(next);document.querySelector(`#solution-tab-${next}`).focus();});});showSolution(0);
  let equipment;
  function showEquipment(index){equipment?.destroy?.();const p=products[index];document.querySelector('#discovery-title').textContent=p[1];document.querySelector('#discovery-description').textContent=p[4];document.querySelector('#discovery-link').href=p[0];document.querySelectorAll('[data-discovery]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.discovery)===index)));document.querySelector('#discovery-stage').innerHTML=`<div class="equipment-stage"><div class="equipment-tools" role="group" aria-label="Equipment studio controls"><button data-equipment="model" aria-pressed="true">3D model</button><button data-equipment="photo" aria-pressed="false">Original photo</button><button data-equipment="motion" aria-pressed="${paused}">${paused?'Play motion':'Pause motion'}</button></div><div class="equipment-canvas" role="img" tabindex="0" aria-label="${p[1]} conceptual 3D model. Drag to rotate or use arrow keys."></div><div class="viewer-zoom"><button data-equipment="zoom-in" aria-label="Zoom in">+</button><button data-equipment="zoom-out" aria-label="Zoom out">−</button><button data-equipment="reset" aria-label="Reset equipment view">↺</button></div><span class="equipment-hint">Drag to rotate · Use + / − to zoom</span></div>`;const photo=content[p[0]]?.images?.[0]||`assets/img/${p[3]}`;equipment=createEquipment(document.querySelector('#discovery-stage .equipment-canvas'),p[0],photo);}
  document.querySelectorAll('[data-discovery]').forEach(b=>b.addEventListener('click',()=>showEquipment(Number(b.dataset.discovery))));showEquipment(11);
  createFacility(document.querySelector('.facility-studio .scene-canvas'));
}
